WITH src(slug, txt, sources) AS (VALUES
  ('gora-ostraya',
   'Острая — гора высотой 1233 м в южной части Камчатки, в Елизовском районе, рядом с селом Сосновка у Елизова. Это популярное место для походов и горных лыж.
С вершины в ясную погоду видны окрестности Вилючинского вулкана, долина Паратунки, вулкан Горелый, Авачинско-Корякская группа вулканов, Авачинская бухта, Петропавловск-Камчатский и Елизово.
Склоны широкие и крутые — около 45 градусов; зимой здесь сходят серьёзные лавины. Горнолыжники катаются на Острой с ноября по июль. Восхождение начинают от стойбища «Пимчах» у Сосновки; подъём и спуск занимают в среднем 10–13 часов.',
   '["https://ru.wikipedia.org/wiki/Острая_(гора,_Елизовский_район,_у_Елизово)", "https://idilesom.com/kam/places/2715"]'::jsonb),
  ('gora-sedlo',
   'Гора Седло высотой около 1115 м стоит недалеко от Елизова, рядом с горой Морозной — одним из лучших горнолыжных центров Камчатки.
Подъём на вершину несложный, его называют маршрутом выходного дня. Пологие склоны покрыты зарослями кедрового стланика, и только у самого верха их сменяют небольшие скальные выступы, которые легко преодолеть. Поход занимает от нескольких часов до целого дня.',
   '["https://idilesom.com/kam/places/2358"]'::jsonb),
  ('hangar',
   'Хангар — вулкан высотой 1967 м, самый южный вулкан Срединного хребта Камчатки; вокруг него берут начало истоки реки Колпаковой. Раньше его считали потухшим, теперь — потенциально активным: последние извержения были около 1000 и около 400 лет назад.
Крупнейшее извержение произошло примерно за 5700 лет до нашей эры и создало вершинный кратер-кальдеру шириной около 2 км. Со временем воронку заполнили осадки, и получилось одно из красивейших кратерных озёр Камчатки — Кожгумк; эвены называют его Ана Геттыген, «Бабушкино озеро». Озеро лежит на высоте около 1420 м, его площадь около 1 км², глубина — больше 150 м. Его окружают обрывистые скалы высотой 150–500 м.
Склоны вулкана сложены сыпучими породами, что заметно затрудняет восхождение.',
   '["https://ru.wikipedia.org/wiki/Хангар_(вулкан)", "https://idilesom.com/kam/places/2714"]'::jsonb),
  ('mertvyj-les',
   'Мёртвый лес — участок выжженной земли площадью около 40 км² у подножия действующего вулкана Плоский Толбачик (3085 м по каталогу KVERT). Когда-то здесь рос зелёный лиственничный лес; после извержения он так и стоит — сухие стволы, засыпанные шлаком и пеплом, а окрестности напоминают лунный пейзаж.
Лес погиб во время Большого трещинного Толбачинского извержения 1975–1976 годов. Это извержение, близкое к гавайскому типу, стало шестым по счёту большим трещинным извержением в историческое время; его заранее предсказали в Институте вулканологии.
Добираются сюда по грунтовой дороге и тропе; на поездку закладывают целый день или несколько дней.',
   '["https://idilesom.com/kam/places/2533", "https://ru.wikipedia.org/wiki/Большое_трещинное_Толбачинское_извержение", "https://ru.wikipedia.org/wiki/Толбачик"]'::jsonb),
  ('pereval-tenueva',
   'Перевал Тенуева высотой около 689 м соединяет долину Нижне-Вилючинских термальных источников с Жировскими источниками в Елизовском районе.
Со стороны Нижне-Вилючинских источников подъём довольно крутой — на тропе натянута верёвка; со стороны Жировских он положе. Тропа идёт через густые заросли кустарника, и время от времени открываются виды на долину реки Жировой вплоть до бухты Жировой. Переход занимает несколько часов.',
   '["https://idilesom.com/kam/places/4293"]'::jsonb),
  ('shishel',
   'Шишель — потухший щитовидный вулкан высотой 2525 м в северной части Камчатки, один из вулканов Срединного хребта. Он стоит в истоках рек Правый Шишей и Левый Шишей; к востоку лежат озёра Междусопочное и Глубокое, к северу от вершины тянутся ледники Левый и Правый Еловский.
Постройка — почти эллиптический щит диаметром около 7 км из базальтов среднего и позднего плейстоцена; вершину осложняет кратер диаметром около 300 м. Хорошая сохранность постройки и лавовых потоков говорит о голоценовом возрасте вулкана.',
   '["https://ru.wikipedia.org/wiki/Шишель_(вулкан)", "https://idilesom.com/kam/places/2896"]'::jsonb),
  ('sopka-glinyanaya',
   'Сопка Глиняная высотой около 1214 м находится в Елизовском районе. Пеший маршрут начинается от заброшенного карьера на высоте около 650 м, куда можно доехать на любой машине.
Около 3 км идут по лесной дороге, а последний участок — довольно крутой подъём через заросли кедрового и ольхового стланика. С вершины видны вулканы Бакенинг, Купол, Дзензур, Ааг, Арик, Корякский, Авачинский, Козельский, Вилючинский, вершина Жупановского, сопки Острая, Козья, Вершинская и Авачинская губа. На поход хватит нескольких часов.',
   '["https://idilesom.com/kam/places/6075"]'::jsonb),
  ('tolmachyova',
   'Толмачёва — потухший щитовой вулкан высотой 1415 м на плато Толмачёв Дол в Усть-Большерецком районе. Последнее его извержение относят к 1400-м годам до нашей эры.
На том же плато лежит озеро Толмачёва подпрудного происхождения: его образовал обвал горных пород в долине реки Толмачёва. С 1999 года озеро входит в Толмачёвское водохранилище площадью 33,45 км²; после строительства ГЭС его уровень вырос на 12 м.',
   '["https://ru.wikipedia.org/wiki/Вулкан_Толмачёва", "https://ru.wikipedia.org/wiki/Озеро_Толмачёва"]'::jsonb),
  ('vulkan-aag',
   'Ааг — потухший вулкан высотой 2310 м, входящий в Авачинско-Корякскую группу вулканов и замыкающий её с северо-запада. Он стоит севернее Корякской сопки; с его предгорий берут начало речки Пиначевская и Дремучая.
Соседняя Корякская сопка — действующий стратовулкан примерно в 35 км к северу от Петропавловска-Камчатского; вместе с Авачинским вулканом она входит в список декадных вулканов ООН.',
   '["https://ru.wikipedia.org/wiki/Ааг", "https://ru.wikipedia.org/wiki/Корякская_Сопка"]'::jsonb)
),
old AS (
  SELECT t.id, t.ark_id AS entity_id, t.name AS title,
         LENGTH(t.description) AS prev_chars, s.txt, s.sources
    FROM places t
    JOIN src s ON s.slug = t.slug
   WHERE char_length(COALESCE(btrim(t.description), '')) < 300
     AND char_length(COALESCE(btrim(t.description), '')) < char_length(s.txt)
     AND NOT EXISTS (
           SELECT 1 FROM description_provenance dp_owner
            WHERE dp_owner.entity_id = t.ark_id
              AND dp_owner.written_by = 'owner-decision')
),
upd AS (
  UPDATE places t
     SET description = old.txt, updated_at = NOW()
    FROM old
   WHERE t.id::text = old.id::text
  RETURNING old.entity_id, old.title, LENGTH(t.description) AS chars, old.prev_chars, old.sources
)
INSERT INTO description_provenance
  (entity_id, entity_kind, entity_title, written_by, facts_given, facts_count, chars, previous_chars)
SELECT upd.entity_id, 'place', upd.title, 'syshchik-sources', upd.sources,
       jsonb_array_length(upd.sources), upd.chars, upd.prev_chars
  FROM upd
 WHERE upd.entity_id IS NOT NULL;

