WITH src(slug, txt, sources) AS (VALUES
  ('barani-skaly-marshrut',
   'Маршрут ведёт к Бараньим скалам — памятнику природы в верховьях реки Студёной, на её правом берегу, у впадения ручья Бараньего (Усть-Камчатский район).
Скалы — обнажения базальтовых столбов. Вода и непогода выточили из них формы, похожие на низко опущенные бараньи лбы с нависшими закрученными рогами, — отсюда и название. На самих скалах растительности нет, лишь в устье ручья растёт кедровый стланик. Правый берег ручья Бараньего и Студёной — место обитания снежного барана.
Путь пеший, по тропе и вдоль берега; на него закладывают целый день или несколько дней.',
   '["https://idilesom.com/kam/places/3127"]'::jsonb),
  ('buhta-anglichanka',
   'Англичанкой неофициально называют местность у побережья Авачинского залива к северу от мыса Маячного, в сторону реки Халактырки. Путешественник К. Дитмар называл её Английским урочищем; на картах это название не сохранилось, но в обиходе живёт до сих пор.
На мысе Скалистом, справа у входа в Авачинскую губу, стояла артиллерийская батарея. Обслуживавшая её часть построила на берегу ручья Морского, рядом с озером Мелким, посёлок Озерный — его и называют Англичанкой.
Сама Авачинская губа — крупная незамерзающая бухта длиной 24 км с шириной входа около 3 км, главные морские ворота Камчатки. Маршрут пеший, по грунтовой дороге и тропе; на него хватит нескольких часов.',
   '["https://idilesom.com/kam/places/2868", "https://ru.wikipedia.org/wiki/Авачинская_бухта"]'::jsonb),
  ('buhta-bechevinskaya',
   'Бечевинская — бухта на севере Авачинского залива, врезающаяся в Шипунский полуостров на северо-восток (Елизовский район). Её ограничивают мыс Ловушек на западе и мыс Входной на востоке; наибольшая глубина — 54 м.
В 1765 году Т. И. Шмалев нанёс бухту на карту как гавань Святого архистратига Гавриила — по кораблю, оставшемуся здесь на зимовку. Название не прижилось: бухту стали звать по фамилии владельца судна, купца И. Бечевина, организатора второй русской экспедиции на Аляску. В 1791 году бухту снимал Г. А. Сарычев.
Добираются сюда по воде и вдоль берега; на поездку закладывают день или несколько дней.',
   '["https://ru.wikipedia.org/wiki/Бечевинская_(бухта)", "https://ru.wikipedia.org/wiki/Авачинский_залив", "https://idilesom.com/kam/places/2745"]'::jsonb),
  ('buhta-kalygir',
   'Бухта Калыгирь отделена от озера Большой Калыгирь узкой песчаной косой длиной около 3,5 км; в самом узком месте её ширина — около 80 м.
Маршрут к бухте пеший, по тропе и вдоль берега, и длинный — на целый день или несколько дней.',
   '["https://idilesom.com/kam/places/2214"]'::jsonb),
  ('buhta-komandora-o-beringa',
   'Бухта Командор находится на юго-восточном берегу острова Беринга — крупнейшего из Командорских островов. В октябре 1741 года здесь встал на якорь пакетбот «Святой Пётр», флагман Второй Камчатской экспедиции. После тяжёлого плавания к берегам Америки измученные нехваткой пресной воды и цингой моряки надеялись, что перед ними Камчатка.
На острове экспедиция зазимовала; здесь находится могила Витуса Беринга и нескольких его спутников. Сам остров длиной около 90 км и шириной до 24 км отделён от Камчатки Камчатским проливом.
Маршрут пеший, вдоль морского берега, на несколько дней; на берегу важно учитывать приливы.',
   '["https://idilesom.com/kam/places/2797", "https://ru.wikipedia.org/wiki/Остров_Беринга"]'::jsonb),
  ('buhta-spaseniya',
   'Бухта Спасения, в обиходе Спасёнка, — одно из самых живописных мест Вилючинска, на берегу Авачинской губы.
Сама Авачинская губа — крупная незамерзающая бухта Тихого океана, внутренняя часть Авачинского залива: длина около 24 км, ширина у входа около 3 км, глубина до 26 м. Её открыли и описали летом 1729 года во время Первой Камчатской экспедиции Витуса Беринга.
К бухте подъезжают по грунтовой дороге; на поездку достаточно нескольких часов. Берег морской, поэтому стоит заранее посмотреть время приливов.',
   '["https://idilesom.com/kam/places/2363", "https://ru.wikipedia.org/wiki/Авачинская_бухта"]'::jsonb),
  ('dembelskij-kamen-marshrut',
   'Дембельский камень — валун высотой меньше двух метров на сопке над Петропавловском-Камчатским, весь расписанный цветными надписями «ДМБ». С этого места открывается красивый вид на город, а вдали видна Авачинская бухта.
Маршрут короткий и несложный: подняться можно от улицы Гастелло или от смотровой площадки; прогулка займёт несколько часов.',
   '["https://idilesom.com/kam/places/3811", "https://ru.wikipedia.org/wiki/Авачинская_бухта"]'::jsonb),
  ('gora-krasnaya-polyana-marshrut',
   'Красная поляна — небольшое плато справа от горы Зайкин мыс (Черельчик) в Елизовском районе; его вершину называют пиком Красной поляны. Название место получило за цвет: осенью поляна становится ярко-красной.
Маршрут пеший, по тропе; на него хватит нескольких часов.',
   '["https://idilesom.com/kam/places/2411"]'::jsonb),
  ('gora-mikizhinskij-mys',
   'Гора Микижинский мыс поднимается над озером Микижа в Елизовском районе. Склоны почти целиком заросли ольховым стлаником, поэтому подниматься лучше по снегу — лучшее время с конца зимы до апреля.
Путь начинается от стоянки базы отдыха «Голубая лагуна» и идёт через озеро. Весной во второй половине дня снег активно тает, между снегом и льдом скапливается вода — слой снежно-водяной каши может доходить до двух метров. Поэтому после обеда по озеру лучше не ходить, а обойти его по берегу. Дальше подъём на хребет; подготовленному человеку на вершину хватит около получаса.',
   '["https://idilesom.com/kam/places/2201"]'::jsonb),
  ('gora-ostraya-marshrut',
   'Острая — гора высотой 1233 м в Елизовском районе, рядом с селом Сосновка у Елизова. С вершины видны Авачинский, Корякский, Козельский, Вилючинский, Мутновский, Горелый и другие вулканы, Тихий океан, Авачинская губа, долины Паратунки и Авачи, Петропавловск-Камчатский и Елизово.
Восхождение начинается от стойбища «Пимчах», куда идут пешком или доезжают на машине от Сосновки. Подъём и спуск в среднем занимают 10–13 часов.
Склоны крутые, около 45 градусов, и зимой гора лавиноопасна. Горнолыжники катаются здесь с ноября по июль.',
   '["https://ru.wikipedia.org/wiki/Острая_(гора,_Елизовский_район,_у_Елизово)", "https://ru.wikipedia.org/wiki/Острая_(гора,_Камчатский_край,_у_ледника_Начикинский)", "https://idilesom.com/kam/places/2715"]'::jsonb),
  ('gora-sedlo-marshrut',
   'Маршрут выходного дня на гору Седло высотой около 1115 м — недалеко от Елизова, рядом с горой Морозной, одним из лучших горнолыжных центров Камчатки.
Подъём несложный: пологие склоны покрыты кедровым стлаником, и только у самой вершины их сменяют небольшие скальные выступы, которые тоже легко пройти. На поход закладывают от нескольких часов до целого дня.',
   '["https://idilesom.com/kam/places/2358"]'::jsonb),
  ('gora-zajkin-mys-chirelchik',
   'Гора Зайкин мыс (Чирельчик) высотой около 968 м стоит недалеко от посёлка Термальный в Елизовском районе.
Маршрут идёт по распадку вдоль ручья до перевала Три Креста, а оттуда — на саму гору. С вершины видны долина реки Паратунки, домашние вулканы, Вилючинский вулкан (2173 м), озеро Дальнее и горы Южно-Быстринского хребта.
Поход занимает от нескольких часов до целого дня.',
   '["https://idilesom.com/kam/places/5480", "https://ru.wikipedia.org/wiki/Вилючинская_Сопка"]'::jsonb),
  ('karymshinskie-termalnye-istochniki-2',
   'Карымшинские термальные источники находятся в Елизовском районе. Вода температурой до 76 °C выходит множеством мелких рассредоточенных струек, которые сразу стекают с обрыва в речку; общий дебит источников — около 2–2,5 л/с.
Большую часть пути проезжают по грунтовой дороге; на поездку хватит нескольких часов.',
   '["https://idilesom.com/kam/places/1519"]'::jsonb),
  ('klyuchevskaya-gruppa-vulkanov-marshrut',
   'Многодневный пеший маршрут по Ключевской группе вулканов — от Толбачиков к Ключевской сопке: Долина Изваяний, восхождение на вулкан Безымянный, ледник Богдановича. По пути часто встречаются евражки, лисы и медведи.
Ключевская группа — крупнейшая группа вулканов России: она занимает около 6,5 тыс. км² в центральной части Камчатки, в нижнем течении реки Камчатки, на стыке Курило-Камчатского и Алеутского вулканических поясов. В группе 13 вулканов, из них четыре действующих — Ключевской, Безымянный, Плоский Толбачик и Дальний Плоский.
Маршрут рассчитан больше чем на неделю.',
   '["https://ru.wikipedia.org/wiki/Ключевская_группа_вулканов", "https://idilesom.com/kam/places/3368"]'::jsonb),
  ('mayak-na-myse-kruglyj',
   'Маяк Круглый стоит на высоком скалистом обрывистом мысе Круглом — южном входном мысе бухты Асача на юго-восточном берегу Камчатки. Название он получил по мысу.
Высота башни — около 14,8 м; маяк находится примерно в 200 м от береговой черты, на высоте около 127 м над уровнем моря.
К маяку идут по грунтовой дороге и вдоль берега; на прогулку закладывают от нескольких часов.',
   '["https://idilesom.com/kam/places/3086"]'::jsonb),
  ('mayak-na-myse-stanitskogo',
   'Маяк Станицкого стоит на мысе Станицкого, на западной стороне пролива, который соединяет Авачинский залив с Авачинской губой.
От маяка грунтовая дорога длиной около 2 км ведёт к пляжу в бухте Станицкого, куда выгружают маячные грузы, а дорога длиной около 7 км — к посёлку Богатырёвка и причалу в бухте Богатырёвка.
Авачинская губа, у входа в которую стоит маяк, — крупная незамерзающая бухта длиной около 24 км, главные морские ворота Камчатки. Поездка по грунтовой дороге займёт несколько часов.',
   '["https://idilesom.com/kam/places/1529", "https://ru.wikipedia.org/wiki/Авачинский_залив", "https://ru.wikipedia.org/wiki/Авачинская_бухта"]'::jsonb),
  ('na-kayakah-po-ozeru-tolmachevo',
   'Многодневный водный маршрут на каяках по озеру Толмачёва в Усть-Большерецком районе, на плато Толмачёв Дол. С разных точек озера видны вулканы Опала, Мутновский и Горелый.
Озеро подпрудного происхождения: оно образовалось, когда обвал горных пород перегородил долину реки Толмачёва. До строительства Толмачёвских ГЭС площадь озера составляла около 15 км², а с 1999 года оно стало частью Толмачёвского водохранилища площадью 33,45 км²; уровень воды вырос с 616 до 627 м над уровнем моря.
Погоду здесь определяет близость западного побережья Камчатки: часто бывают облачность и западные ветра. До озера от Петропавловска-Камчатского около 200 км на машине.',
   '["https://ru.wikipedia.org/wiki/Озеро_Толмачёва", "https://ru.wikipedia.org/wiki/Вулкан_Толмачёва", "https://idilesom.com/kam/places/6052"]'::jsonb),
  ('ostrov-mandzhur',
   'Остров Манджур находится в Карагинском районе. До начала XX века он носил местное название Инушсемень, которое помнят и нынешние жители-коряки. Название Маньчжур (Манджур) острову дали офицеры канонерской лодки «Маньчжур», нанёсшие его на карту до 1904 года.
Добраться до острова можно только по воде; поездка занимает несколько дней.',
   '["https://idilesom.com/kam/places/3091"]'::jsonb),
  ('ostrov-utashud',
   'Остров Уташуд — группа из трёх скалистых островков напротив устья реки Вестник, у юго-восточного берега Камчатки. Их плоские вершины сплошь покрыты дёрном, у воды стоят остроконечные кекуры, а среди рифов виден корпус затонувшего судна.
Остров необитаем, но богат жизнью: здесь одна из богатейших популяций каланов, лежбища антуров и ларг, гнездовья топорков и чаек. Летом у побережья часто держится небольшое стадо серых китов.
Добираются к острову по воде; на поездку закладывают от целого дня.',
   '["https://idilesom.com/kam/places/2722"]'::jsonb),
  ('palanskie-porogi-2',
   'Паланские пороги — каскад порогов на реке Палане в Тигильском районе. Река протекает через Паланское озеро запрудного типа, а на выходе из него устремляется по узкому извилистому ущелью среди отвесных берегов, образуя стремнины и пороги вокруг огромных валунов. Шум порогов разносится на несколько километров.
Пороги — памятник природы и часть регионального заказника «Озеро Паланское». Сама Палана длиной 141 км впадает в залив Шелихова Охотского моря; у её устья стоит посёлок Палана.
Маршрут долгий, по грунтовой дороге, на несколько дней. Для посещения заказника нужно специальное разрешение.',
   '["https://idilesom.com/kam/places/3092", "https://ru.wikipedia.org/wiki/Палана_(река)"]'::jsonb),
  ('plato-antarktida-marshrut',
   'Плато Антарктида лежит на высоте около 2650 м в Ключевской группе вулканов и со всех сторон окружено вулканами. От посёлка Ключи до него около 44 км пути, около 2500 м набора высоты и один несложный перевал.
Ключевская группа — крупнейшая группа вулканов России: около 6,5 тыс. км², 13 вулканов, из них четыре действующих — Ключевской, Безымянный, Плоский Толбачик и Дальний Плоский.
Маршрут пеший, по тропе, на несколько дней.',
   '["https://idilesom.com/kam/places/2746", "https://ru.wikipedia.org/wiki/Ключевская_группа_вулканов"]'::jsonb),
  ('poselok-prizrak',
   'Посёлок-призрак — это заброшенный военный городок Бечевинка (Финвал) у бухты Бечевинской на Шипунском полуострове, примерно в 80 км от Петропавловска-Камчатского. Долгое время место было закрытым.
Посёлок основали в 1960-х годах как базу подводных лодок; в августе 1971 года сюда перевели 182-ю отдельную бригаду подводных лодок. Здесь построили восемь жилых домов в три — пять этажей, котельную, почту, магазин, школу и детский сад. В 1996 году лодки перебазировали в Завойко, гарнизон расформировали, жителей вывезли, а в 1998 году городок упразднили.
Сейчас дома стоят пустыми и разрушаются, поэтому заходить внутрь опасно. Подъезд — по грунтовой дороге, на поездку закладывают целый день.',
   '["https://ru.wikipedia.org/wiki/Бечевинка_(Камчатский_край)", "https://idilesom.com/kam/places/6637"]'::jsonb),
  ('sopka-petrovskaya-marshrut',
   'Сопка Петровская — сопка высотой около 270 м в Петропавловске-Камчатском со смотровой площадкой на вершине. Отсюда видны Авачинская бухта, Вилючинский вулкан, океан и домашние вулканы.
Авачинская бухта — одна из крупнейших бухт мира, способная принять любое судно: длина около 24 км, площадь водного зеркала около 215 км², в неё впадают реки Авача и Паратунка. Подъём на сопку короткий, прогулка займёт несколько часов.',
   '["https://idilesom.com/kam/places/3770", "https://ru.wikipedia.org/wiki/Авачинская_бухта"]'::jsonb),
  ('splav-po-reke-bystraya',
   'Многодневный сплав по реке Быстрой — одной из самых популярных рек для сплава на Камчатке. Течение местами действительно быстрое, вокруг живописные сопки. В реке водятся голец, кижуч, хариус и нерка, поэтому здесь много рыбаков — и много медведей.
Быстрая — верхнее течение реки Большой: ниже впадения Плотниковой река называется уже Большой. Её общая длина — 275 км; начинается она в Ганальском хребте и впадает в Охотское море. У слияния Быстрой и Плотниковой когда-то стоял Большерецк, важный для освоения Камчатки острог.',
   '["https://ru.wikipedia.org/wiki/Большая_(река,_впадает_в_Охотское_море)", "https://idilesom.com/kam/places/6638"]'::jsonb),
  ('vilyuchinskij-pereval-marshrut',
   'Вилючинский перевал лежит у подножия Вилючинского вулкана в Елизовском районе. В хорошую погоду отсюда видны сразу несколько вулканов, среди них Мутновский и Горелый, а с другой стороны открывается долина реки Паратунки. На перевале стоят три тотема.
Вилючинский — потухший стратовулкан правильной конической формы высотой 2173 м на водоразделе рек Вилюча и Большая Саранная, в верховьях Паратунки. Его вершина срезана к западу, склоны прорезаны глубокими радиальными оврагами-барранкосами.
Маршрут пеший, по тропе, на целый день.',
   '["https://ru.wikipedia.org/wiki/Вилючинская_Сопка", "https://idilesom.com/kam/places/6322", "https://ru.wikipedia.org/wiki/Горелый_(вулкан)"]'::jsonb),
  ('vodopad-medvezhij',
   'Водопад Медвежий стоит на притоке ручья Медвежьего — отсюда и название — примерно в 7 км от пещер вулкана Горелого.
От стоянки машины к водопаду ведёт тропа длиной около километра вниз по склонам разной крутизны; в августе по пути много ягод.
Горелый — действующий вулкан высотой 1829,7 м на юге Камчатки: пять перекрывающихся стратовулканов в кальдере размером 10 × 13 км, около 11 конусов и 30 кратеров, некоторые заполнены кислотой или пресной водой. На прогулку к водопаду закладывают целый день.',
   '["https://idilesom.com/kam/places/1517", "https://ru.wikipedia.org/wiki/Горелый_(вулкан)"]'::jsonb),
  ('zelenovskie-ozerki-marshrut',
   'Зеленовские озерки — термальные минеральные источники примерно в 15 км от Елизова и в 45 км от Петропавловска-Камчатского. Вода в них содержит радон.
При источниках построен водно-оздоровительный бальнеологический центр с десятью ваннами, температуру воды в которых можно регулировать. Подъезд — по асфальту и грунтовой дороге; на поездку достаточно нескольких часов.',
   '["https://idilesom.com/kam/places/2824"]'::jsonb),
  ('zimnee-sap-puteshestvie-po-reke-paratunka-2',
   'Зимний маршрут на сап-бордах по реке Паратунке — от базы отдыха «Фламинго» до станции гидрологов у впадения реки Микижи.
Паратунка начинается в предгорьях Вилючинского вулкана и течёт на север, мимо Елизова, Вилючинска и Петропавловска-Камчатского, к Авачинской бухте; её длина — 81 км. Название реки связывают с именем Паратуна — ительменского (по другим данным — айнского) шамана, который первым стал лечить соплеменников горячими источниками. В долине реки три группы термальных источников.
Маршрут занимает целый день.',
   '["https://idilesom.com/kam/places/6064", "https://ru.wikipedia.org/wiki/Паратунка_(река)"]'::jsonb)
),
old AS (
  SELECT t.id, COALESCE(t.ark_id, t.id) AS entity_id, t.title AS title,
         LENGTH(t.description) AS prev_chars, s.txt, s.sources
    FROM kamchatka_routes t
    JOIN src s ON s.slug = t.slug
   WHERE char_length(COALESCE(btrim(t.description), '')) < 300
     AND char_length(COALESCE(btrim(t.description), '')) < char_length(s.txt)
     AND NOT EXISTS (
           SELECT 1 FROM description_provenance dp_owner
            WHERE dp_owner.entity_id = COALESCE(t.ark_id, t.id)
              AND dp_owner.written_by = 'owner-decision')
),
upd AS (
  UPDATE kamchatka_routes t
     SET description = old.txt, updated_at = NOW()
    FROM old
   WHERE t.id::text = old.id::text
  RETURNING old.entity_id, old.title, LENGTH(t.description) AS chars, old.prev_chars, old.sources
)
INSERT INTO description_provenance
  (entity_id, entity_kind, entity_title, written_by, facts_given, facts_count, chars, previous_chars)
SELECT upd.entity_id, 'route', upd.title, 'syshchik-sources', upd.sources,
       jsonb_array_length(upd.sources), upd.chars, upd.prev_chars
  FROM upd
 WHERE upd.entity_id IS NOT NULL;
